components.css:
.ds-panel { background: var(--color-panel-veil, rgba(21, 32, 43, 0.88)); backdrop-filter: blur(14px); border: 1px solid var(--color-border, #24313d); border-radius: 8px; padding: 1.5rem; max-width: 24rem; color: var(--color-text-primary, #e6edf2); }
.ds-panel__sentence { margin: 0; font-family: 'Noto Serif Thai', 'Trirong', serif; font-size: clamp(1.375rem, 1rem + 2vw, 2.125rem); line-height: 1.65; text-wrap: balance; }
.ds-panel__numbers { display: flex; flex-wrap: wrap; gap: 0.5rem 1rem; margin: 1rem 0 0; }
.ds-panel__numbers dt { display: flex; align-items: center; gap: 0.25rem; font-size: 0.75rem; color: var(--color-text-faint, #8494a0); }
.ds-panel__numbers dd { margin: 0; font-size: 0.875rem; color: var(--color-text-secondary, #a4b4bf); font-variant-numeric: tabular-nums lining-nums; }
.ds-dot { width: 0.5rem; height: 0.5rem; border-radius: 999px; display: inline-block; }
.ds-dot--hollow { background: transparent; border: 2px solid var(--color-text-faint, #8494a0); }
.ds-panel__meta { margin: 1rem 0 0; font-size: 0.75rem; color: var(--color-text-faint, #8494a0); font-variant-numeric: tabular-nums lining-nums; }

.ds-btn-primary { font-family: 'Mahanathi Sans', 'Noto Sans Thai', sans-serif; font-size: 0.875rem; font-weight: 600; color: var(--color-text-primary, #e6edf2); background: var(--color-panel, #15202b); border: 1px solid var(--color-border-strong, #33434f); border-radius: 8px; padding: 0.5rem 1rem; cursor: pointer; transition: background 200ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-btn-primary:hover { background: var(--color-hover, #1f2e3c); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--color-focus-ring, #7fb5b0); outline-offset: 2px; }

.ds-sheet { background: var(--color-panel-veil, rgba(21, 32, 43, 0.88)); backdrop-filter: blur(14px); border: 1px solid var(--color-border, #24313d); border-radius: 12px; padding: 1rem 1.5rem; color: var(--color-text-primary, #e6edf2); }
.ds-sheet__name { margin: 0; font-family: 'Mahanathi Sans', 'Noto Sans Thai', sans-serif; font-size: 1.125rem; font-weight: 600; line-height: 1.5; }
.ds-sheet__sentence { margin: 0.5rem 0 0; font-family: 'Noto Serif Thai', 'Trirong', serif; font-size: 1.125rem; line-height: 1.6; text-wrap: balance; }
.ds-sheet__numbers { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0.75rem 1.5rem; margin: 1rem 0 0; }
.ds-sheet__numbers dt { font-size: 0.75rem; color: var(--color-text-faint, #8494a0); }
.ds-sheet__numbers dd { margin: 0; font-size: 0.875rem; color: var(--color-text-primary, #e6edf2); font-variant-numeric: tabular-nums lining-nums; }

.ds-chip { font-family: 'Mahanathi Sans', 'Noto Sans Thai', sans-serif; font-size: 0.75rem; color: var(--color-text-secondary, #a4b4bf); background: var(--color-panel, #15202b); border: 1px solid var(--color-border, #24313d); border-radius: 999px; padding: 0.25rem 0.75rem; cursor: pointer; transition: color 160ms cubic-bezier(0.16, 1, 0.3, 1), border-color 160ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-chip:hover { color: var(--color-text-primary, #e6edf2); }
.ds-chip:focus-visible { outline: 2px solid var(--color-focus-ring, #7fb5b0); outline-offset: 2px; }
.ds-chip--active { color: var(--color-text-primary, #e6edf2); border-color: var(--color-border-strong, #33434f); }

.ds-error { display: flex; flex-direction: column; align-items: center; gap: 1rem; max-width: 24rem; padding: 1.5rem; text-align: center; background: var(--color-panel, #15202b); border: 1px solid var(--color-border, #24313d); border-radius: 8px; }
.ds-error p { margin: 0; font-family: 'Mahanathi Sans', 'Noto Sans Thai', sans-serif; font-size: 0.875rem; line-height: 1.55; color: var(--color-text-primary, #e6edf2); text-wrap: balance; }
.ds-error button { font-family: 'Mahanathi Sans', 'Noto Sans Thai', sans-serif; font-size: 0.875rem; font-weight: 600; color: var(--color-text-primary, #e6edf2); background: var(--color-hover, #1f2e3c); border: 1px solid var(--color-border-strong, #33434f); border-radius: 4px; padding: 0.5rem 1.5rem; cursor: pointer; }
.ds-error button:focus-visible { outline: 2px solid var(--color-focus-ring, #7fb5b0); outline-offset: 2px; }

.ds-skeleton { position: absolute; inset: 0; background: linear-gradient(100deg, transparent 30%, rgba(255, 255, 255, 0.015) 50%, transparent 70%) var(--color-ground, #0e161d); background-size: 300% 100%; animation: ds-sweep 1.6s cubic-bezier(0.16, 1, 0.3, 1) infinite; }
@keyframes ds-sweep { from { background-position: 120% 0; } to { background-position: -120% 0; } }
@media (prefers-reduced-motion: reduce) { .ds-skeleton { animation: none; } }
